// northStar - what Content Studio should be, rendered at /north-star (Leo's sign-ins only). Leo, 2026-10-19:
// "the idea is that one can remix any content format and the ai will regenerate". Built from his screen
// recording of Fastlane, 126 competitors' sourced features and an inventory of the app at origin/main 08537d1.
//
// Keep it current: when an item ships or changes, flip its `status` and its `ours` line in the same commit.
// Item ids are URL anchors (/north-star#<id>) and spec file names (docs/north-star/items/<id>.md), so never
// rename one. Start at docs/north-star/README.md. Generated once on 2026-10-19; edit by hand from now on.

export type NsStatus = "live" | "partial" | "missing";

export type NsArea = "find" | "remix" | "formats" | "people" | "brand" | "plan" | "edit" | "publish" | "learn" | "agent" | "trust" | "business";

export interface NsItem {
  id: string;
  area: NsArea;
  title: string;
  status: NsStatus;
  /** Build order, see NS_PHASES. */
  phase: number;
  /** How the best competitors do it, Fastlane first, with their numbers. */
  they: string;
  /** What Content Studio has today, and where it lives. */
  ours: string;
  /** What to build to close the gap. */
  build: string;
  /** Competitor ids (src/data/northStarCompetitors.ts) that do it well, the most useful first. */
  seenIn: string[];
  /** Seconds of Leo's Fastlane recording that show it: public/north-star/fastlane/<frame>.webp. */
  frames?: string[];
  /** The one call only Leo can make for this item, if any (more in the spec's Open questions). */
  question?: string;
}

export interface NsAsk {
  id: string;
  date: string;
  /** Leo's words. */
  text: string;
  short: string;
  items: string[];
}

