/** A frame ref is "t176" (the tour) or "<recording id>:tSSS", e.g. "review:t013". */
export function parseFrame(ref: string): { rec: NsRecording; t: string } | null {
  const [id, t] = ref.includes(":") ? ref.split(":") : ["tour", ref];
  const rec = RECORDINGS.find((r) => r.id === id);
  return rec && /^t\d{3}$/.test(t ?? "") ? { rec, t } : null;
}

export const frameRef = (rec: NsRecording, t: string) => (rec.id === "tour" ? t : `${rec.id}:${t}`);

export const frameSrc = (ref: string) => {
  const p = parseFrame(ref);
  return p ? `/north-star/${p.rec.dir}/${p.t}.webp` : "";
};

export interface NsDogfoodPost {
  n: number;
  date: string;
  format: string;
  kind: "templated" | "ai";
  angle: string;
  /** The hook as it shows on the post, verbatim. */
  hook: string;
  frame?: string;
  /** Ours only: each slide as made, in order (public/north-star/dogfood). */
  slides?: string[];
  /** Ours only: how it did against the same Fastlane slot. */
  note?: string;
}

