export function rollup(items: NsItem[]): Record<NsStatus, number> {
  const r: Record<NsStatus, number> = { live: 0, partial: 0, missing: 0 };
  for (const i of items) r[i.status] += 1;
  return r;
}

/** "t125" or "review:t125" -> "2:05". */
export const frameLabel = (f: string) => {
  const s = Number(f.slice(f.lastIndexOf("t") + 1));
  return `${Math.floor(s / 60)}:${String(s % 60).padStart(2, "0")}`;
};

export const specUrl = (id: string) => `https://github.com/leotansingapore/content-studio/blob/main/docs/north-star/items/${id}.md`;

/** What a Claude session needs to build one item, pasted as its first message. */
export const buildPrompt = (i: NsItem) =>
  [
    `Build north-star item "${i.title}" (${i.id}) in content-studio (github.com/leotansingapore/content-studio).`,
    `1. Read docs/north-star/README.md, then docs/north-star/items/${i.id}.md, and open every frame it links.`,
    "2. Work in your own worktree from origin/main. Check \"What we have today\" against the code before you change anything.",
    "3. Gate it with leoOnly(email) from src/lib/leoOnly.ts. Stop and ask Leo before a schema change, a new dependency, an auth change or anything that costs money.",
    "4. Meet every line under \"Done when\". Run npm run build and npx vitest run, and look at it at 390 px and 1440 px.",
    `5. In the same commit, set the item's status and ours line in src/data/northStar.ts. Then git pull --rebase origin main and git push origin main.`,
  ].join("\n");
